import { mkdirSync, mkdtempSync, realpathSync } from 'node:fs';
import path from 'node:path';
import { tmpdir } from 'node:os';
import { expect, it } from 'vitest';
import { admissionFixture } from './fixtures/scout-admission.js';
import { reserveScoutAttempt, finishScoutAttempt } from '../src/scout/runAdmission.js';
const now = Date.parse('2026-10-16T09:00:00Z');
function fixture() {
 const root=realpathSync(mkdtempSync(path.join(tmpdir(),'qa-adversarial-scope-')));
 const workspace=path.join(root,'workspace'); const repo=path.join(workspace,'repo'); mkdirSync(repo,{recursive:true});
 const scope={runId:'run-qa',askId:'ask-qa',workspace,repo,sourceHead:'a'.repeat(40)};
 const f=admissionFixture(scope,now,root); return {...f,scope};
}
it.each(['source','confidence'])('reproduces admitted capacity with missing %s', field => {
 const f=fixture(); delete (f.evidence.capacity as any)[field]; f.pin();
 const token=reserveScoutAttempt(f.stores,f.evidence,f.scope,'scripted-fixture',now);
 expect(token.attempt).toBe(1); console.log('MISSING_CAPACITY_FIELD_ADMITTED',field);
});
it.each(["You've hit your usage limit. Try again later.", 'Not logged in'])('reproduces admitted retry after terminal refusal %s',(failure)=>{
 const f=fixture(); const token=reserveScoutAttempt(f.stores,f.evidence,f.scope,'scripted-fixture',now);
 finishScoutAttempt(f.stores,f.evidence.isolation.pins.fixtureRoot,token,{failure,retryable:true},now+1);
 expect(f.read().attempts[0].retryable).toBe(true);
 const later=now+90_000; f.scope.sourceHead='b'.repeat(40); f.evidence.scope={...f.scope}; f.evidence.assignment.scope={...f.scope};
 f.evidence.codeReview.sourceHead=f.scope.sourceHead; f.evidence.qa.sourceHead=f.scope.sourceHead; f.evidence.isolation.pins.sourceRevision=f.scope.sourceHead;
 f.evidence.isolation.before!.takenAt=new Date(later).toISOString(); f.evidence.isolation.after!.takenAt=new Date(later).toISOString(); f.evidence.capacity.observedAt=new Date(later).toISOString();
 f.evidence.retry={failure,previousReservation:token.id,verifiedFix:'candidate fix'}; f.pin();
 expect(reserveScoutAttempt(f.stores,f.evidence,f.scope,'scripted-fixture',later).attempt).toBe(2);
});

